function design(site, analyse) {
  const xs = [0, 4.108, 8.217, 12.325, 16.433, 20.542, 24.65,
              28.758, 32.867, 36.975, 41.083, 45.192, 49.3];

  const chord = [
    "CHS139.7x6.3", "CHS168.3x6.3", "CHS193.7x8", "CHS219.1x8",
    "CHS244.5x8", "CHS273x10", "CHS323.9x10", "CHS355.6x12.5",
    "CHS406.4x12.5", "CHS457x16"
  ];
  const levels = {
    bottom: chord,
    upper: chord,
    post: [
      "CHS114.3x5", "CHS139.7x6.3", "CHS168.3x6.3", "CHS193.7x8",
      "CHS219.1x8", "CHS244.5x8", "CHS273x10", "CHS323.9x10",
      "CHS355.6x12.5", "CHS406.4x12.5"
    ],
    diagonal: [
      "CHS76.1x4", "CHS88.9x5", "CHS114.3x5", "CHS139.7x6.3",
      "CHS168.3x6.3", "CHS193.7x8", "CHS219.1x8", "CHS244.5x8",
      "CHS273x10", "CHS323.9x10", "CHS355.6x12.5"
    ],
    deckGirder: [
      "CHS76.1x4", "CHS88.9x5", "CHS114.3x5", "CHS139.7x6.3",
      "CHS168.3x6.3", "CHS193.7x8", "CHS219.1x8", "CHS244.5x8"
    ],
    roofGirder: [
      "CHS33.7x2.6", "CHS42.4x3.2", "CHS48.3x3.2", "CHS60.3x3.2",
      "CHS60.3x4", "CHS76.1x4", "CHS88.9x5", "CHS114.3x5",
      "CHS139.7x6.3", "CHS168.3x6.3"
    ],
    deckBrace: [
      "CHS33.7x2.6", "CHS42.4x3.2", "CHS48.3x3.2", "CHS60.3x3.2",
      "CHS60.3x4", "CHS76.1x4", "CHS88.9x5", "CHS114.3x5"
    ],
    roofBrace: [
      "CHS33.7x2.6", "CHS42.4x3.2", "CHS48.3x3.2", "CHS60.3x3.2",
      "CHS60.3x4", "CHS76.1x4", "CHS88.9x5", "CHS114.3x5"
    ]
  };
  const roles = Object.keys(levels);
  const seed = {
    bottom: 6, upper: 6, post: 7, diagonal: 9,
    deckGirder: 4, roofGirder: 6, deckBrace: 5, roofBrace: 5
  };

  function cloneIndices(src) {
    const out = {};
    for (const k of roles) out[k] = src[k];
    return out;
  }

  function topId(side, i) {
    return "T" + side + i;
  }

  function midId(side, i) {
    return "TM" + side + i;
  }

  function makeDesign(H, idx) {
    const nodes = [];
    const members = [];

    for (const side of ["L", "R"]) {
      const z = side === "L" ? -3.05 : 3.05;
      for (let i = 0; i <= 12; i++) {
        nodes.push({ id: topId(side, i), x: xs[i], y: H, z: z, joint: "pin" });
      }
      for (let i = 0; i < 12; i++) {
        nodes.push({
          id: midId(side, i),
          x: (xs[i] + xs[i + 1]) / 2,
          y: H,
          z: z,
          joint: "pin"
        });
      }
    }

    function add(a, b, role) {
      members.push([a, b, "S460 " + levels[role][idx[role]]]);
    }

    // Lower chords, split upper chords, and vertical posts of the two Pratt trusses.
    for (let i = 0; i < 12; i++) {
      add("L" + i, "L" + (i + 1), "bottom");
      add("R" + i, "R" + (i + 1), "bottom");

      add(topId("L", i), midId("L", i), "upper");
      add(midId("L", i), topId("L", i + 1), "upper");
      add(topId("R", i), midId("R", i), "upper");
      add(midId("R", i), topId("R", i + 1), "upper");
    }
    for (let i = 0; i <= 12; i++) {
      add("L" + i, topId("L", i), "post");
      add("R" + i, topId("R", i), "post");
    }

    // Pratt diagonals rise toward midspan under gravity loading.
    for (let i = 0; i < 12; i++) {
      if (i < 6) {
        add("L" + i, topId("L", i + 1), "diagonal");
        add("R" + i, topId("R", i + 1), "diagonal");
      } else {
        add("L" + (i + 1), topId("L", i), "diagonal");
        add("R" + (i + 1), topId("R", i), "diagonal");
      }
    }

    // Deck cross-girders and triangulation in the deck plane.
    for (let i = 0; i <= 12; i++) add("L" + i, "R" + i, "deckGirder");
    for (let i = 0; i < 12; i++) {
      add("L" + i, "R" + (i + 1), "deckBrace");
      add("R" + i, "L" + (i + 1), "deckBrace");
    }

    // Cross-girders and X-bracing in the roof plane.
    const topPairs = [];
    for (let i = 0; i <= 12; i++) {
      topPairs.push({ l: topId("L", i), r: topId("R", i) });
      if (i < 12) {
        topPairs.push({ l: midId("L", i), r: midId("R", i) });
      }
    }
    for (const p of topPairs) add(p.l, p.r, "roofGirder");
    for (let i = 0; i + 1 < topPairs.length; i++) {
      add(topPairs[i].l, topPairs[i + 1].r, "roofBrace");
      add(topPairs[i].r, topPairs[i + 1].l, "roofBrace");
    }

    return {
      note: "Pinned twin Pratt trusses use triangulated deck and roof planes, with sections selected by analysis.",
      nodes: nodes,
      members: members
    };
  }

  function numberOrNull(x) {
    if (x === undefined || x === null || x === "") return null;
    const n = Number(x);
    return Number.isFinite(n) ? n : null;
  }

  function ratio(a, b) {
    const x = numberOrNull(a);
    const y = numberOrNull(b);
    return x === null || y === null || y <= 0 ? null : x / y;
  }

  function safe(r) {
    if (!r || r.error || r.ok !== true) return false;

    const mu = numberOrNull(r.maxUtil);
    if (mu !== null && mu > 0.60) return false;

    let cr = numberOrNull(r.alphaCrMin);
    if (cr === null) cr = numberOrNull(r.alphaCr);
    if (cr !== null && cr < 5.5) return false;

    const sagRatio = ratio(r.sag, r.sagLimit);
    if (sagRatio !== null && sagRatio > 0.82) return false;

    const swayRatio = ratio(r.sway, r.swayLimit);
    if (swayRatio !== null && swayRatio > 0.82) return false;

    const f = numberOrNull(r.frequency);
    if (f !== null && f < 2.35) return false;

    const fatigue = numberOrNull(r.fatigueWorst);
    if (fatigue !== null && fatigue > 0.78) return false;

    const rob = r.robustness;
    if (rob === false) return false;
    if (rob && typeof rob === "object" &&
        (rob.ok === false || rob.pass === false || rob.passed === false)) return false;

    return true;
  }

  function quality(r) {
    if (!r || r.error) return -1e12;
    let q = r.ok === true ? 100000 : 0;

    const mu = numberOrNull(r.maxUtil);
    if (mu !== null) q -= Math.max(0, mu - 0.50) * 400;

    let cr = numberOrNull(r.alphaCrMin);
    if (cr === null) cr = numberOrNull(r.alphaCr);
    if (cr !== null) q -= Math.max(0, 5.8 - cr) * 60;

    const sr = ratio(r.sag, r.sagLimit);
    if (sr !== null) q -= Math.max(0, sr - 0.75) * 180;

    const wr = ratio(r.sway, r.swayLimit);
    if (wr !== null) q -= Math.max(0, wr - 0.75) * 180;

    const f = numberOrNull(r.frequency);
    if (f !== null) q -= Math.max(0, 2.4 - f) * 120;

    const fatigue = numberOrNull(r.fatigueWorst);
    if (fatigue !== null) q -= Math.max(0, fatigue - 0.70) * 180;

    if (r.robustness === false) q -= 1000;

    const mass = numberOrNull(r.mass);
    if (mass !== null) q -= mass * 0.0001;
    return q;
  }

  let calls = 0;
  const callLimit = 105;
  let bestAny = null;
  let bestSafe = null;

  function remember(rec) {
    if (!bestAny || quality(rec.r) > quality(bestAny.r)) bestAny = rec;
    if (safe(rec.r) &&
        (!bestSafe ||
         numberOrNull(rec.r.mass) < numberOrNull(bestSafe.r.mass))) {
      bestSafe = rec;
    }
  }

  function run(H, idx) {
    if (calls >= callLimit) return null;
    calls++;
    const d = makeDesign(H, idx);
    let r;
    try {
      r = analyse(d);
    } catch (e) {
      r = { error: String(e) };
    }
    const rec = { H: H, idx: cloneIndices(idx), d: d, r: r };
    remember(rec);
    return rec;
  }

  const starts = [];
  for (const H of [5.8, 6.2, 6.6]) {
    const rec = run(H, seed);
    if (rec) starts.push(rec);
  }

  let current = bestSafe;
  if (!current && starts.length) {
    current = starts[0];
    for (const rec of starts) {
      if (quality(rec.r) > quality(current.r)) current = rec;
    }

    // If needed, enlarge one member family at a time, guided by the report.
    for (let round = 0; round < 4 && calls < callLimit && !bestSafe; round++) {
      let nextBest = null;
      let nextSafe = null;
      for (const role of roles) {
        if (calls >= callLimit) break;
        if (current.idx[role] + 1 >= levels[role].length) continue;
        const nextIdx = cloneIndices(current.idx);
        nextIdx[role]++;
        const rec = run(current.H, nextIdx);
        if (!rec) continue;
        if (safe(rec.r)) {
          if (!nextSafe ||
              numberOrNull(rec.r.mass) < numberOrNull(nextSafe.r.mass)) {
            nextSafe = rec;
          }
        } else if (!nextBest || quality(rec.r) > quality(nextBest.r)) {
          nextBest = rec;
        }
      }
      if (nextSafe) {
        current = nextSafe;
        break;
      }
      if (!nextBest || quality(nextBest.r) <= quality(current.r)) break;
      current = nextBest;
    }
  }

  if (bestSafe) {
    current = bestSafe;

    // Greedy coordinate descent while retaining conservative analysis margins.
    for (let pass = 0; pass < 8 && calls < callLimit; pass++) {
      let changed = false;
      for (const role of roles) {
        if (calls >= callLimit) break;
        if (current.idx[role] <= 0) continue;
        const nextIdx = cloneIndices(current.idx);
        nextIdx[role]--;
        const rec = run(current.H, nextIdx);
        if (rec && safe(rec.r)) {
          current = rec;
          changed = true;
        }
      }
      if (!changed) break;
    }
  }

  if (bestSafe) {
    bestSafe.d.note =
      "Pinned twin Pratt trusses use triangulated deck and roof planes, with sections selected by analysis.";
    return bestSafe.d;
  }
  if (bestAny) {
    bestAny.d.note =
      "Pinned twin Pratt trusses use triangulated deck and roof planes, with sections selected by analysis.";
    return bestAny.d;
  }
  return makeDesign(6.2, seed);
}

function design(site, analyse) {
  const xs = [0,4.108,8.217,12.325,16.433,20.542,24.65,28.758,32.867,36.975,41.083,45.192,49.3];
  const L = 49.3;

  function build(p) {
    const nodes = [], members = [], seen = new Set();

    function addNode(id,x,y,z) {
      nodes.push({id:id, x:x, y:y, z:z, joint:"pin"});
    }
    function addMember(a,b,spec) {
      if (!spec || a === b) return;
      const key = a < b ? (a+"|"+b) : (b+"|"+a);
      if (seen.has(key)) return;
      seen.add(key);
      members.push([a,b,spec]);
    }

    let topIdx;
    if (p.topIdx) topIdx = p.topIdx.slice();
    else {
      topIdx = [];
      for (let i = p.topStep; i < 12; i += p.topStep) topIdx.push(i);
    }

    const topY = {};
    for (let k = 0; k < topIdx.length; k++) {
      const i = topIdx[k], x = xs[i];
      let y = p.f * 4 * x * (L - x) / (L*L);
      if (y > 16.30) y = 16.30;
      topY[i] = y;
      addNode("AL"+i, x, y, -3.05);
      addNode("AR"+i, x, y,  3.05);
    }

    function topNode(side,i) {
      if (i === 0) return side === "L" ? "L0" : "R0";
      if (i === 12) return side === "L" ? "L12" : "R12";
      return (side === "L" ? "AL" : "AR") + i;
    }

    const pts = [0].concat(topIdx, [12]).sort(function(a,b){return a-b;});

    // Arch chords
    for (let si = 0; si < 2; si++) {
      const side = si === 0 ? "L" : "R";
      for (let k = 0; k < pts.length - 1; k++) {
        addMember(topNode(side,pts[k]), topNode(side,pts[k+1]), p.arch);
      }
    }

    // Continuous deck tie / bottom chord
    if (p.bottomChord) {
      for (let i = 0; i < 12; i++) {
        addMember("L"+i, "L"+(i+1), p.tie);
        addMember("R"+i, "R"+(i+1), p.tie);
      }
    }

    // Vertical hangers at arch panel points
    if (p.addHangers) {
      for (let k = 0; k < topIdx.length; k++) {
        const i = topIdx[k];
        if (i > 0 && i < 12) {
          const y = topY[i];
          if (y > 14.4) {
            const idL = "HL"+i, idR = "HR"+i;
            addNode(idL, xs[i] + 0.8, y/2, -3.05);
            addNode(idR, xs[i] + 0.8, y/2,  3.05);
            addMember("L"+i, idL, p.hanger);
            addMember(idL, topNode("L",i), p.hanger);
            addMember("R"+i, idR, p.hanger);
            addMember(idR, topNode("R",i), p.hanger);
          } else {
            addMember("L"+i, topNode("L",i), p.hanger);
            addMember("R"+i, topNode("R",i), p.hanger);
          }
        }
      }
    }

    // Inclined side-web members
    for (let i = 1; i <= 11; i++) {
      const isTop = topIdx.indexOf(i) >= 0;
      if (isTop && !p.diagAtTop) continue;

      let left = 0, right = 12;
      for (let k = 0; k < pts.length; k++) {
        const t = pts[k];
        if (t < i && t > left) left = t;
        if (t > i && t < right) right = t;
      }

      if (left !== i) {
        addMember("L"+i, topNode("L",left), p.sideDiag);
        addMember("R"+i, topNode("R",left), p.sideDiag);
      }
      if (right !== i) {
        addMember("L"+i, topNode("L",right), p.sideDiag);
        addMember("R"+i, topNode("R",right), p.sideDiag);
      }
    }

    // Deck transverse beams
    for (let i = 0; i <= 12; i++) {
      addMember("L"+i, "R"+i, p.crossDeck);
    }

    // Bottom lateral bracing
    if (p.bottomBraceMode === "X" || p.bottomBraceMode === "zig") {
      for (let i = 0; i < 12; i++) {
        if (p.bottomBraceMode === "X") {
          addMember("L"+i, "R"+(i+1), p.bottomBrace);
          addMember("R"+i, "L"+(i+1), p.bottomBrace);
        } else {
          if (i % 2 === 0) addMember("L"+i, "R"+(i+1), p.bottomBrace);
          else addMember("R"+i, "L"+(i+1), p.bottomBrace);
        }
      }
    }

    // Top cross-beams and lateral bracing
    for (let k = 0; k < topIdx.length; k++) {
      const i = topIdx[k];
      if (i > 0 && i < 12) {
        addMember(topNode("L",i), topNode("R",i), p.topCross);
      }
    }

    function yOf(i) {
      if (i === 0 || i === 12) return 0;
      return topY[i] !== undefined ? topY[i] : 0;
    }

    for (let k = 0; k < topIdx.length - 1; k++) {
      const a = topIdx[k], b = topIdx[k+1];
      if (Math.min(yOf(a), yOf(b)) < 5.3) continue;
      if (p.topBraceMode === "X") {
        addMember(topNode("L",a), topNode("R",b), p.topBrace);
        addMember(topNode("R",a), topNode("L",b), p.topBrace);
      } else if (p.topBraceMode === "zig") {
        if (k % 2 === 0) addMember(topNode("L",a), topNode("R",b), p.topBrace);
        else addMember(topNode("R",a), topNode("L",b), p.topBrace);
      }
    }

    return {note:p.note, nodes:nodes, members:members};
  }

  let calls = 0;
  const cache = new Map();

  function evalD(params) {
    const key = JSON.stringify(params);
    if (cache.has(key)) return cache.get(key);
    if (calls >= 380) return null;
    calls++;
    let r;
    try {
      r = analyse(build(params));
    } catch (e) {
      r = {error:String(e)};
    }
    cache.set(key, r);
    return r;
  }

  function isSafe(r, level) {
    if (!r || r.error || r.ok === false) return false;
    if (r.maxUtil !== undefined && r.maxUtil !== null && r.maxUtil > level.util) return false;
    if (r.alphaCr !== undefined && r.alphaCr !== null && r.alphaCr < level.alpha) return false;
    if (r.frequency !== undefined && r.frequency !== null && r.frequency < level.freq) return false;
    if (r.sag !== undefined && r.sag !== null && r.sagLimit && r.sag > level.sag * r.sagLimit) return false;
    if (r.sway !== undefined && r.sway !== null && r.swayLimit && r.sway > level.sway * r.swayLimit) return false;
    if (r.robustness === false) return false;
    return true;
  }

  const strict = {util:0.75, alpha:6.0, freq:2.55, sag:0.70, sway:0.70};
  const relaxed = {util:0.90, alpha:4.5, freq:2.20, sag:0.90, sway:0.90};

  function optimize(base, opts, level) {
    let cur = JSON.parse(JSON.stringify(base));
    let curR = evalD(cur);
    if (!curR || curR.error || curR.ok === false) {
      return {params:cur, r:curR};
    }

    const groups = Object.keys(opts);
    for (let pass = 0; pass < 2; pass++) {
      let improved = false;
      for (let gi = 0; gi < groups.length; gi++) {
        const g = groups[gi];
        let localBest = null, localR = null;
        const vals = opts[g];
        for (let vi = 0; vi < vals.length; vi++) {
          const opt = vals[vi];
          if (opt === cur[g]) continue;
          const trial = JSON.parse(JSON.stringify(cur));
          trial[g] = opt;
          const r = evalD(trial);
          if (r && r.ok && isSafe(r, level)) {
            if (!localR || r.mass < localR.mass) {
              localR = r;
              localBest = trial;
            }
          }
        }
        if (localBest && localR && (!curR || curR.ok === false || localR.mass < curR.mass)) {
          cur = localBest;
          curR = localR;
          improved = true;
        }
      }
      if (!improved) break;
    }
    return {params:cur, r:curR};
  }

  const opts = {
    arch: [
      "S460 CHS193.7x6.3",
      "S460 CHS193.7x8",
      "S460 CHS219.1x8",
      "S460 CHS244.5x8",
      "S460 CHS273x10"
    ],
    tie: [
      "S460 CHS139.7x6.3",
      "S460 CHS168.3x6.3",
      "S460 CHS193.7x6.3",
      "S460 CHS193.7x8",
      "S460 CHS219.1x8"
    ],
    hanger: [
      "S460 CHS88.9x4",
      "S460 CHS114.3x4",
      "S460 CHS114.3x5",
      "S460 CHS139.7x6.3",
      "S460 CHS168.3x6.3"
    ],
    sideDiag: [
      "S460 CHS76.1x4",
      "S460 CHS88.9x4",
      "S460 CHS114.3x4",
      "S460 CHS114.3x5",
      "S460 CHS139.7x5"
    ],
    crossDeck: [
      "S460 CHS76.1x4",
      "S460 CHS88.9x4",
      "S460 CHS114.3x4",
      "S460 CHS114.3x5",
      "S460 CHS139.7x5"
    ],
    bottomBrace: [
      "S460 CHS60.3x3.2",
      "S460 CHS76.1x4",
      "S460 CHS88.9x4",
      "S460 CHS114.3x4"
    ],
    topCross: [
      "S460 CHS76.1x4",
      "S460 CHS88.9x4",
      "S460 CHS114.3x4",
      "S460 CHS114.3x5",
      "S460 CHS139.7x5"
    ],
    topBrace: [
      "S460 CHS60.3x3.2",
      "S460 CHS76.1x4",
      "S460 CHS88.9x4",
      "S460 CHS114.3x4"
    ]
  };

  const baseT1 = {
    topStep:2, f:13.5, bottomChord:true, diagAtTop:false, addHangers:true,
    arch:"S460 CHS273x10",
    tie:"S460 CHS219.1x8",
    hanger:"S460 CHS168.3x6.3",
    sideDiag:"S460 CHS139.7x5",
    crossDeck:"S460 CHS139.7x5",
    bottomBrace:"S460 CHS114.3x4",
    topCross:"S460 CHS139.7x5",
    topBrace:"S460 CHS114.3x4",
    bottomBraceMode:"X", topBraceMode:"zig",
    note:"S460 tied through-arch truss with continuous deck tie and cross bracing"
  };

  const baseT1z = JSON.parse(JSON.stringify(baseT1));
  baseT1z.bottomBraceMode = "zig";
  baseT1z.note = "S460 tied through-arch truss with zig-zag deck bracing";

  const baseT2 = JSON.parse(JSON.stringify(baseT1));
  baseT2.bottomChord = false;
  baseT2.diagAtTop = true;
  baseT2.addHangers = false;
  baseT2.bottomBraceMode = "X";
  baseT2.note = "S460 through-arch with inclined hanger web and X deck bracing";

  const cands = [];

  let o1 = optimize(baseT1, opts, strict);
  cands.push(o1);

  let o2 = optimize(baseT1z, opts, strict);
  cands.push(o2);

  function bestFrom(list, level) {
    let best = null;
    for (let i = 0; i < list.length; i++) {
      const c = list[i];
      if (c && c.r && c.r.ok && isSafe(c.r, level)) {
        if (!best || c.r.mass < best.r.mass) best = c;
      }
    }
    return best;
  }

  let best = bestFrom(cands, strict);

  if (!best) {
    let o3 = optimize(baseT1, opts, relaxed);
    cands.push(o3);
    best = bestFrom(cands, relaxed);
  }

  if (!best) {
    let o4 = optimize(baseT2, opts, relaxed);
    cands.push(o4);
    best = bestFrom(cands, relaxed);
  }

  if (!best) {
    let anyOk = null;
    for (let i = 0; i < cands.length; i++) {
