    let r = null;
    try { r = analyse(d); } catch (e) { r = null; }
    const res = {
      lv: lv.slice(),
      d: d,
      ok: !!(r && r.ok === true),
      mass: (r && typeof r.mass === "number") ? r.mass : Infinity
    };
    cache[key] = res;
    return res;
  }

  const NOTE = "Two 12 m deep pinned Pratt trusses at z = ±3.05 with deck-level and top-level X-bracing and struts; CHS sizes per group found by a uniform search followed by greedy size reduction against analyse.";

  // Uniform search: smallest level where every group has the same tier index
  let cur = null;
  for (let k = 3; k <= 7 && !cur; k++) {
    const r = evalLevels([k, k, k, k, k, k]);
    if (!r) break;
    if (r.ok) cur = r;
  }
  if (!cur) {
    const r = evalLevels([7, 7, 7, 7, 7, 7]);
    const d = r ? r.d : build([7, 7, 7, 7, 7, 7]);
    return { note: NOTE, nodes: d.nodes, joints: d.joints, members: d.members };
