      lv[g] -= 1;
      const r = evalLevels(lv);
      if (r && r.ok && r.mass < cur.mass) {
        cur = r;
        improved = true;
      }
    }
  }

  return { note: NOTE, nodes: cur.d.nodes, joints: cur.d.joints, members: cur.d.members };
}

