    const br = (a, b, spec) => pinBr ? { a: a, b: b, spec: spec, ends: "pin" } : [a, b, spec];
    for (let i = 0; i < 12; i++) {
      members.push(["L" + i, "L" + (i + 1), S.bc]);
      members.push(["R" + i, "R" + (i + 1), S.bc]);
      members.push(["TL" + i, "TL" + (i + 1), S.tc]);
      members.push(["TR" + i, "TR" + (i + 1), S.tc]);
      if (i < 6) {
        members.push(br("TL" + i, "L" + (i + 1), S.d));
        members.push(br("TR" + i, "R" + (i + 1), S.d));
      } else {
        members.push(br("TL" + (i + 1), "L" + i, S.d));
        members.push(br("TR" + (i + 1), "R" + i, S.d));
      }
      members.push(br("L" + i, "R" + (i + 1), S.ld));
      members.push(br("R" + i, "L" + (i + 1), S.ld));
      members.push(br("TL" + i, "TR" + (i + 1), S.lt));
      members.push(br("TR" + i, "TL" + (i + 1), S.lt));
    }
    for (let i = 0; i <= 12; i++) {
      members.push(["L" + i, "TL" + i, S.v]);
      members.push(["R" + i, "TR" + i, S.v]);
      members.push(br("L" + i, "R" + i, S.ls));
      members.push(br("TL" + i, "TR" + i, S.ts));
    }
    return { note: NOTE, nodes: nodes, joints: joints, members: members };
  }

  const t0 = Date.now();
  let calls = 0;
  const cache = {};

  function ev(idx, pinBr) {
    const key = idx.join(",") + "|" + pinBr;
    if (cache[key]) return cache[key];
    if (calls >= 170 || Date.now() - t0 > 72000) return null;
    calls += 1;
    const d = build(idx, pinBr);
    let r = null;
    try { r = analyse(d); } catch (e) { r = null; }
    const res = {
      idx: idx.slice(),
      pinBr: pinBr,
      d: d,
      ok: !!(r && r.ok === true),
      mass: (r && typeof r.mass === "number") ? r.mass : Infinity
    };
    cache[key] = res;
    return res;
  }

  const top = G.map(g => TIER[g].length - 1);
  let cur = null;
  let fallback = null;
  for (const pb of [true, false]) {
    const r = ev(top, pb);
    if (!r) break;
    if (!fallback) fallback = r;
    if (r.ok) { cur = r; break; }
  }
  if (!cur) {
    const d = fallback ? fallback.d : build(top, false);
    return { note: NOTE, nodes: d.nodes, joints: d.joints, members: d.members };
  }

  let improved = true;
  while (improved) {
    improved = false;
    for (let g = 0; g < G.length; g++) {
      if (cur.idx[g] <= 0) continue;
      const idx = cur.idx.slice();
      idx[g] -= 1;
      const r = ev(idx, cur.pinBr);
      if (r && r.ok && r.mass < cur.mass) {
        cur = r;
        improved = true;
      }
    }
  }

  const alt = ev(cur.idx, !cur.pinBr);
  if (alt && alt.ok && alt.mass < cur.mass) cur = alt;

  return { note: NOTE, nodes: cur.d.nodes, joints: cur.d.joints, members: cur.d.members };
}
